<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\SoftDeletes;
class AttendanceDevice extends Model { use SoftDeletes; protected $fillable=['device_name','device_code','device_type','vendor','model','serial_number','connection_type','protocol','ip_address','port','connection_timeout','http_method','authentication_type','api_url','api_key','api_secret','username','password','import_format','file_path','delimiter','timezone','location','company_id','branch_id','sync_mode','auto_sync_enabled','sync_frequency','status','last_sync_at','last_successful_sync_at','remarks','description','created_by','updated_by']; protected $hidden=['api_key','api_secret','username','password']; protected $casts=['api_key'=>'encrypted','api_secret'=>'encrypted','username'=>'encrypted','password'=>'encrypted','auto_sync_enabled'=>'boolean','last_sync_at'=>'datetime','last_successful_sync_at'=>'datetime']; public function mappings(){return $this->hasMany(AttendanceDeviceEmployeeMapping::class,'device_id');} public function logs(){return $this->hasMany(AttendanceDeviceLog::class,'device_id');} public function syncLogs(){return $this->hasMany(AttendanceDeviceSyncLog::class,'device_id');} }
